package com.pulsepay.ledger;
import com.pulsepay.security.MerchantPrincipal; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/ledger") public class LedgerController {private final JdbcTemplate db;private final LedgerService ledger;public LedgerController(JdbcTemplate db,LedgerService ledger){this.db=db;this.ledger=ledger;} record ReversalRequest(String reason){} @GetMapping public List<Map<String,Object>> list(@AuthenticationPrincipal MerchantPrincipal p){return db.query("select j.transaction_reference,j.event_type,j.currency,j.posted_at,a.name,e.debit_minor,e.credit_minor,e.description from ledger_entries e join ledger_journals j on j.id=e.journal_id join ledger_accounts a on a.id=e.account_id where j.merchant_id=? order by j.posted_at desc",(rs,i)->Map.of("journal",rs.getString(1),"type",rs.getString(2),"currency",rs.getString(3),"posted_at",rs.getTimestamp(4).toInstant().toString(),"account",rs.getString(5),"debit_minor",rs.getLong(6),"credit_minor",rs.getLong(7),"description",rs.getString(8)),p.merchantId());} @PostMapping("/journals/{reference}/reverse") @Transactional public Map<String,Object> reverse(@AuthenticationPrincipal MerchantPrincipal p,@PathVariable String reference,@RequestBody ReversalRequest request){UUID id=ledger.reverse(p.merchantId(),reference,request.reason()==null||request.reason().isBlank()?"Correction":request.reason());db.update("insert into audit_logs(merchant_id,actor_user_id,action,resource_type,resource_id)values(?,?,?,'ledger_journal',?)",p.merchantId(),p.userId(),"ledger.journal_reversed",id);return Map.of("journal_id",id,"transaction_reference","reversal:"+reference);}}
